package com.bank.cashback.service;

import java.util.logging.Logger;

// Maximum non-adjacent sum: linear DP with two rolling variables.
public class CashbackOptimizerService {
    private static final Logger log = Logger.getLogger(CashbackOptimizerService.class.getName());

    public long maxNonAdjacentCashback(int[] amounts) {
        long twoBack = 0;                                 // best ending 2 days before
        long oneBack = 0;                                 // best ending the previous day
        for (int v : amounts) {
            long take = twoBack + v;                      // take today → skip yesterday
            long best = Math.max(oneBack, take);          // skip today vs take today
            twoBack = oneBack;                            // roll the window forward
            oneBack = best;
        }
        final long result = oneBack;
        log.info(() -> "Maximum non-adjacent cash-back = " + result);
        return oneBack;
    }
}
