package com.bank.cashback;

import com.bank.cashback.service.CashbackOptimizerService;
import java.util.logging.Logger;

public class CashbackOptimizerApplication {
    private static final Logger log = Logger.getLogger(CashbackOptimizerApplication.class.getName());

    public static void main(String[] args) {
        CashbackOptimizerService service = new CashbackOptimizerService();
        int[] daily = {2, 7, 9, 3, 1};                    // daily cash-back units
        long best = service.maxNonAdjacentCashback(daily);
        log.info(() -> "Final best cash-back total = " + best);
    }
}
